      x: 0.5, y: rowY, w: 0.4, h: 0.4,
      fill: { color: COLORS.accent }
    });
    slide8.addText(item.num, {
      x: 0.5, y: rowY, w: 0.4, h: 0.4,
      fontSize: 14, fontFace: "Arial", bold: true,
      color: COLORS.white, align: "center", valign: "middle"
    });

    // Title and detail
    slide8.addText(item.title, {
      x: 1.05, y: rowY, w: 8.4, h: 0.35,
      fontSize: 14, fontFace: "Arial", bold: true,
      color: COLORS.white
    });
    slide8.addText(item.detail, {
      x: 1.05, y: rowY + 0.32, w: 8.4, h: 0.38,
      fontSize: 11, fontFace: "Calibri",
      color: COLORS.iceBlue
    });
  });

  // Forward looking footer
  slide8.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 5.0, w: 10, h: 0.625,
    fill: { color: COLORS.darkNavy }
  });
  slide8.addText("The ultra sound money thesis depends on on-chain activity recovery. Watch gas levels — they're the canary in the coal mine for ETH's deflationary future.", {
    x: 0.5, y: 5.1, w: 9, h: 0.45,
    fontSize: 11, fontFace: "Calibri", italic: true,
    color: COLORS.iceBlue, align: "center"
  });

  // Save
  await pres.writeFile({ fileName: "/app/output/final_deck.pptx" });
  console.log("Presentation saved to /app/output/final_deck.pptx");
}

