const pptxgen = require("pptxgenjs");
const React = require("react");
const ReactDOMServer = require("react-dom/server");
const sharp = require("sharp");
const { FaCoins, FaChartLine, FaFire, FaLock, FaGlobe, FaCheckCircle } = require("react-icons/fa");

// Color palette - Midnight Executive with ETH-themed accents
const COLORS = {
  navy: "1E2761",
  darkNavy: "141B40",
  iceBlue: "CADCFC",
  accent: "627EEA",    // ETH blue
  accentLight: "8BA4F6",
  white: "FFFFFF",
  lightGray: "F8FAFC",
  muted: "94A3B8",
  darkText: "1E293B",
  success: "10B981",   // Green for burn/positive
  warning: "F59E0B",   // Amber for caution
  danger: "EF4444",    // Red for issuance/negative
};

async function renderIconSvg(IconComponent, color = "#000000", size = 256) {
  const svg = await ReactDOMServer.renderToStaticMarkup(
    React.createElement(IconComponent, { color, size: String(size) })
  );
  return svg;
}

async function iconToBase64Png(IconComponent, color, size = 256) {
  const svg = await renderIconSvg(IconComponent, color, size);
  const pngBuffer = await sharp(Buffer.from(svg)).png().toBuffer();
  return "image/png;base64," + pngBuffer.toString("base64");
}

function makeShadow(opacity = 0.12) {
  return { type: "outer", blur: 8, offset: 3, angle: 135, color: "000000", opacity };
}

async function createPresentation() {
  const pres = new pptxgen();
  pres.layout = "LAYOUT_16x9";
  pres.title = "Ultra Sound Money: Ethereum's Post-Merge Supply Dynamics";
  pres.author = "Ultra Sound Money";

  // Pre-render icons
  const iconCoins = await iconToBase64Png(FaCoins, "#" + COLORS.accent, 256);
  const iconChart = await iconToBase64Png(FaChartLine, "#" + COLORS.accent, 256);
  const iconFire = await iconToBase64Png(FaFire, "#" + COLORS.accent, 256);
  const iconLock = await iconToBase64Png(FaLock, "#" + COLORS.accent, 256);
  const iconGlobe = await iconToBase64Png(FaGlobe, "#" + COLORS.accent, 256);
  const iconCheck = await iconToBase64Png(FaCheckCircle, "#" + COLORS.accent, 256);

  // ========== SLIDE 1: Title ==========
  const slide1 = pres.addSlide();
  slide1.background = { color: COLORS.navy };

  // Decorative accent bar at top
  slide1.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: 10, h: 0.08,

